263	        let digest = digest_reader(&b"abc"[..]).unwrap();
264	        let hex = digest.to_hex();
265	
266	        // 原始字节与十六进制文本表达同一个值。
267	        let mut from_bytes = String::with_capacity(64);
268	        for byte in digest.as_bytes() {
269	            use std::fmt::Write as _;
270	            let _ = write!(from_bytes, "{byte:02x}");
271	        }
