143	/// 生成可安全输出到标准错误的路径文本：不可解码的字节以替换字符
144	/// （U+FFFD）呈现，控制字符转义为可见写法。该文本只用于显示。
145	fn path_display(path: &Path) -> String {
146	    let lossy = path.to_string_lossy();
147	    if !lossy.contains(char::is_control) {
148	        return lossy.into_owned();
149	    }
150	    let mut out = String::with_capacity(lossy.len());
151	    for ch in lossy.chars() {
152	        match ch {
153	            '\t' => out.push_str("\\t"),
154	            '\n' => out.push_str("\\n"),
155	            '\r' => out.push_str("\\r"),
156	            c if c.is_control() => {
157	                use std::fmt::Write as _;
158	                let _ = write!(out, "\\u{{{:x}}}", c as u32);
159	            }
160	            c => out.push(c),
161	        }
162	    }
